+        margin: 0;
+        max-width: 60ch;
+        color: var(--muted);
+        line-height: 1.6;
+      }
+
+      .faq {
+        display: grid;
+        gap: 16px;
+      }
+
+      .example {
+        border: 1px solid var(--border);
+        border-radius: 20px;
+        background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent),
+          var(--panel);
+        box-shadow: var(--shadow);
+        overflow: hidden;
+      }
+
+      .question {
+        width: 100%;
+        border: 0;
+        background: transparent;
+        color: var(--text);
+        cursor: pointer;
+        padding: 20px 22px;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 20px;
+        text-align: left;
+        font-size: 1.05rem;
+        font-weight: 700;
+      }
+
+      .question:hover {
+        background: rgba(255, 255, 255, 0.03);
+      }
+
+      .question:focus-visible {
+        outline: 2px solid var(--accent);
+        outline-offset: -2px;
+      }
+
+      .icon {
+        flex: 0 0 auto;
+        width: 38px;
+        height: 38px;
+        border-radius: 50%;
+        display: grid;
+        place-items: center;
+        background: var(--panel-2);
+        color: var(--accent);
+        transition: transform 180ms ease, background 180ms ease;
+      }
+
+      .example.is-open .icon {
+        transform: rotate(45deg);
+        background: rgba(143, 183, 255, 0.16);
+      }
+
+      .details {
+        display: grid;
+        grid-template-rows: 0fr;
+        transition: grid-template-rows 220ms ease;
+        border-top: 1px solid transparent;
+      }
+
+      .example.is-open .details {
+        grid-template-rows: 1fr;
+        border-top-color: var(--border);
+      }
+
+      .details > div {
+        overflow: hidden;
+      }
+
+      .details p {
+        margin: 0;
+        padding: 0 22px 22px;
+        color: var(--muted);
+        line-height: 1.7;
+      }
+
+      .tag {
+        display: inline-block;
+        margin-top: 10px;
+        padding: 6px 10px;
+        border-radius: 999px;
+        background: rgba(108, 229, 193, 0.12);
+        color: var(--accent-2);
+        font-size: 0.875rem;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100% - 20px, 900px);
+          padding-top: 28px;
+        }
+
+        .question {
+          padding: 18px;
+        }
+
+        .details p {
+          padding: 0 18px 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main class="page">
+      <header>
+        <h1>Cat FAQ</h1>
+        <p class="subtitle">A cozy, collapsible guide to a few common cat questions.</p>
+      </header>
+
+      <section class="faq" aria-label="Frequently asked questions about cats">
+        <div class="example">
+          <button class="question" aria-expanded="false">
+            <span>Why do cats purr?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" hidden>
+            <div>
+              <p>Cats often purr when they feel relaxed and comfortable, but they may also purr when they are stressed or healing. It is one of their most versatile ways of communicating.</p>
+            </div>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" aria-expanded="false">
+            <span>Do cats need baths?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" hidden>
+            <div>
+              <p>Most cats groom themselves well and do not need regular baths. A bath is usually only needed if they get into something sticky, dirty, or unsafe for them to lick off.</p>
+            </div>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" aria-expanded="false">
+            <span>Why do cats knead blankets?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" hidden>
+            <div>
+              <p>Kneading is a comfort behavior that often starts in kittenhood. Adult cats may do it when they feel safe, content, or especially attached to a cozy spot.</p>
+            </div>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" aria-expanded="false">
+            <span>How much sleep do cats need?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" hidden>
+            <div>
+              <p>Many cats sleep 12 to 16 hours a day, and some sleep even more. Their bursty hunting instincts mean they save energy with lots of short naps.</p>
+              <span class="tag">Nap experts</span>
+            </div>
+          </div>
+        </div>
+      </section>
+    </main>
+
+    <script>
+      document.querySelectorAll(".example").forEach((example) => {
+        const button = example.querySelector(".question");
+        const details = example.querySelector(".details");
+
+        button.addEventListener("click", () => {
+          const isOpen = example.classList.toggle("is-open");
+          button.setAttribute("aria-expanded", String(isOpen));
+          details.hidden = !isOpen;
+        });
+      });
+    </script>
+  </body>
+</html>
*** End Patch
